"""Industry plans, architecture decisions, and client-side resource discovery."""
from pathlib import Path
from html import escape as e
import json
from ai_workflows import all_guides
from ai_implementation import COLLECTIONS, STYLE

BASE = Path(__file__).parent
INDUSTRIES = json.loads((BASE/'content/ai-industries.json').read_text())
DECISIONS = json.loads((BASE/'content/ai-decisions.json').read_text())
ROOT = '/ai/implementation/'
DATE = '2026-10-24'
GLOSSARY = [
('retrieval-augmented-generation','Retrieval-augmented generation (RAG)','A workflow that retrieves relevant source material and supplies it when generating an answer.','A policy assistant retrieves the current service policy before drafting its response.','A retrieved passage still needs the right authority, access permissions, and effective date.','/ai/implementation/decisions/rag-vs-fine-tuning/'),
('fine-tuning','Fine-tuning','Adapting model behavior through a training process using examples or other training signals.','A team evaluates training examples for a specialized classification task.','Training does not remove the need for a held-out evaluation set or current business evidence.','/ai/implementation/decisions/rag-vs-fine-tuning/'),
('semantic-search','Semantic search','Retrieval that uses representations of meaning to find related material.','A question about faster replacements retrieves a passage titled expedited replacement.','Check exact identifiers and similar product names separately.','/ai/implementation/decisions/keyword-vs-semantic-search/'),
('hybrid-search','Hybrid search','Retrieval combining keyword and meaning-based signals.','A knowledge base must support product codes and paraphrased customer questions.','A combined method still needs evaluation against relevant passages.','/ai/implementation/decisions/keyword-vs-semantic-search/'),
('context-window','Context window','The bounded input and output space a model can work with for a request, subject to its implementation limits.','A long document collection must be selected or summarized before use.','Fitting material into a request does not prove every relevant detail will be used correctly.','/ai/implementation/decisions/prompt-vs-context-engineering/'),
('context-engineering','Context engineering','Designing the evidence, instructions, tools, and state available for a task.','A customer brief receives the verified account ID and current notes.','Keep source material distinct from operating instructions.','/ai/implementation/decisions/prompt-vs-context-engineering/'),
('structured-output','Structured output','A response organized to a defined field and type contract.','An intake result has a case ID, category, and explicit unknown values.','Correct structure does not establish factual accuracy.','/ai/implementation/decisions/structured-output-vs-free-text/'),
('tool-calling','Tool calling','A mechanism for a model to request operations from defined external functions or services.','An assistant requests a lookup using a verified work-order ID.','The tool service must enforce authorization and input validation.','/ai/implementation/agents-and-integrations/agent-tool-contracts/'),
('idempotency','Idempotency','A property allowing repeated execution of the same operation without multiplying its intended effect.','A retried task-creation request recovers the existing task.','A prompt asking the agent to avoid duplicates is not a durable duplicate-prevention mechanism.','/ai/implementation/agents-and-integrations/idempotency-and-retries/'),
('evaluation-set','Evaluation set','A collection of task cases with expected behavior or judging criteria.','An intake classifier is tested on routine, ambiguous, and missing-data requests.','Keep release cases separate from examples used to tune the implementation.','/ai/implementation/knowledge-and-evaluation/evaluation-dataset-design/'),
('regression-test','Regression test','A repeatable check for behavior lost or changed after an update.','A new model is tested against the old version on the same critical cases.','Average improvement can hide a severe failure in one category.','/ai/implementation/knowledge-and-evaluation/model-change-regression/'),
('abstention','Abstention','Withholding an unsupported answer and returning a useful clarification or escalation.','A policy assistant cannot find an approved source and names the responsible owner.','Track unnecessary refusals as well as unsupported answers.','/ai/implementation/knowledge-and-evaluation/abstention-and-escalation/'),
('human-in-the-loop','Human in the loop','A person participates at a defined review or decision point.','A manager approves the exact customer communication before sending.','Name what the person verifies and bind approval to the action version.','/ai/implementation/agents-and-integrations/human-approval-inbox/'),
('provenance','Evidence provenance','The traceable origin and version history of information used in an output.','A claim links to a document ID, version, and supporting passage.','A real citation can still fail to support the associated claim.','/ai/implementation/knowledge-and-evaluation/citation-verification/'),
('batch-processing','Batch processing','Submitting independent tasks for asynchronous processing and later reconciliation.','An overnight job reviews a backlog of completed support records.','Track success and failure per item instead of assuming submission equals completion.','/ai/implementation/decisions/batch-vs-realtime-ai/'),
('cost-per-accepted-output','Cost per accepted output','Total operating cost divided by deliverables meeting the acceptance standard.','The denominator excludes rejected drafts while costs include their review and rework.','State what costs and acceptance rules were included before comparing workflows.','/ai/implementation/roi-calculator/')]


def resources():
    rows=[]
    for c,g in all_guides():
        rows.append((g['title'],f"/ai/{c['slug']}/{g['slug']}/",c['title'],g['query']))
    for slug,title,desc,guides in COLLECTIONS:
        rows.extend((g[1],ROOT+slug+'/'+g[0]+'/',title,g[2]) for g in guides)
    rows.extend((g['title'],ROOT+'industries/'+g['slug']+'/', 'Industry plans',g['summary']) for g in INDUSTRIES)
    rows.extend((g['title'],ROOT+'decisions/'+g['slug']+'/', 'Architecture decisions',g['summary']) for g in DECISIONS)
    return rows


def render_pages(header,breadcrumbs,footer,site_url,person_id):
    pages={}
    def page(title,desc,path,body,kind='WebPage',parent=None):
        crumbs=[('Home','/'),('AI Implementation Library',ROOT)]
        if parent:crumbs.append(parent)
        crumbs.append((title,None))
        schema=[]
        if kind=='TechArticle':
            schema=[{'@type':'TechArticle','headline':title,'datePublished':DATE,'dateModified':DATE,'author':{'@id':person_id},'mainEntityOfPage':site_url+path}]
        pages[path]=header(title,desc,path,extra=STYLE,crumbs=crumbs,page_type='CollectionPage' if kind=='CollectionPage' else 'WebPage',schema_nodes=schema)+breadcrumbs(crumbs)+f'<section class="pg-hero"><div class="ctn"><h1>{e(title)}</h1><p>{e(desc)}</p></div></section><section class="sec"><div class="ctn impl-content">{body}</div></section>'+footer()
    def links(rows):return '<ul class="link-list">'+''.join(f'<li><a href="{e(url)}">{e(title)}</a></li>' for title,url in rows)+'</ul>'
    def cards(rows):return '<div class="impl-grid">'+''.join(f'<article class="impl-card"><h2><a href="{url}">{e(title)}</a></h2><p>{e(desc)}</p></article>' for title,url,desc in rows)+'</div>'
    def table(head,rows):return '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse"><thead><tr>'+''.join('<th scope="col" style="text-align:left;padding:12px;border-bottom:1px solid #888">'+e(c)+'</th>' for c in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td style="vertical-align:top;padding:12px;border-bottom:1px solid #777">'+e(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
    for n,g in enumerate(INDUSTRIES):
        path=ROOT+'industries/'+g['slug']+'/'
        body=f'<p>By <a href="/about/">Dr. Connor Robertson</a> · Published October 24, 2026 · Industry implementation plan</p><h2>Where the operating value comes from</h2><p>{e(g["problem"])}</p><p><strong>First deliverable:</strong> {e(g["deliverable"])}.</p><h2>The source material to prepare</h2><p>{e(g["inputs"])}</p><p>Choose a source owner and establish which record wins when versions disagree. Use approved sample records before connecting live systems. The purpose of the pilot is to see whether the team can accept the output with less total effort.</p><h2>Three distinct workflows</h2>'+table(['Workflow','AI preparation','Human decision','Measure'],g['workflows'])+f'<h2>A worked exception</h2><p>{e(g["example"])}</p><h2>Build the first pilot</h2><ol>'+''.join('<li>'+e(s)+'</li>' for s in g['steps'])+f'</ol><h2>Exception handling and boundaries</h2><p>{e(g["exceptions"])}</p><h2>What the next operator needs</h2><p>{e(g["handoff"])}</p><p>Measure preparation, review, corrections, and the time to an accepted deliverable. Record unsuccessful attempts as well as successful ones. A draft that shifts work to another team should appear in the pilot’s cost and quality record.</p><h2>Continue with the task guides</h2>'+links(g['related']+[['AI pilot readiness planner',ROOT+'readiness-planner/'],['AI workflow ROI calculator',ROOT+'roi-calculator/'],[INDUSTRIES[(n+1)%len(INDUSTRIES)]['title'],ROOT+'industries/'+INDUSTRIES[(n+1)%len(INDUSTRIES)]['slug']+'/']])
        page(g['title'],g['summary'],path,body,'TechArticle',('Industry plans',ROOT+'industries/'))
    page('AI Implementation by Industry','Eight operating plans with distinct deliverables, source requirements, exception cases, and review ownership.',ROOT+'industries/','<p>Choose the operating setting that resembles your team. Each plan connects three workflows to a concrete first deliverable and a worked exception. These are illustrative implementation designs, not claimed client results.</p>'+cards([(g['title'],ROOT+'industries/'+g['slug']+'/',g['summary']) for g in INDUSTRIES])+'<p><a href="'+ROOT+'directory/">Search every AI guide</a> or <a href="'+ROOT+'readiness-planner/">prepare a pilot readiness plan</a>.</p>','CollectionPage')
    for n,g in enumerate(DECISIONS):
        path=ROOT+'decisions/'+g['slug']+'/'
        body=f'<p>By <a href="/about/">Dr. Connor Robertson</a> · Published October 24, 2026 · Architecture decision guide</p><h2>The short answer</h2><p>{e(g["answer"])}</p><h2>Compare the operating choices</h2>'+table(['Decision dimension',g['left'],g['right']],g['rows'])+f'<h2>A business scenario</h2><p>{e(g["scenario"])}</p><p>This example is illustrative. Use your own approved records and business constraints to decide whether the same distinction applies. Write the failure you want to remove before choosing a technology.</p><h2>A practical decision process</h2><ol>'+''.join('<li>'+e(s)+'</li>' for s in g['steps'])+f'</ol><h2>Acceptance test</h2><p>{e(g["test"])}</p><h2>The mistake to avoid</h2><p>{e(g["trap"])}</p><h2>Record the choice</h2><p>Save the alternatives considered, the evidence from your trial, the accepted quality threshold, and the maintenance owner. Include a condition that would cause you to revisit the decision: a changed source collection, a new deadline, a different output contract, or a new failure pattern.</p><p>Do not compare one approach on clean examples and the other on difficult ones. Reuse the same approved cases and count the complete path to an accepted result, including review, retries, and reconciliation.</p><h2>Reference and next steps</h2><p>For the underlying technical mechanism, consult <a href="{g["source"]}">{e(g["source_label"])}</a>. Product limits, supported models, and implementation details can change; check the current documentation before building.</p>'+links([['Related implementation playbook',g['related']],['AI business glossary',ROOT+'glossary/'],[DECISIONS[(n+1)%len(DECISIONS)]['title'],ROOT+'decisions/'+DECISIONS[(n+1)%len(DECISIONS)]['slug']+'/']])
        page(g['title'],g['summary'],path,body,'TechArticle',('Architecture decisions',ROOT+'decisions/'))
    page('AI Architecture Decision Guides','Six practical comparisons for choosing retrieval, training, processing modes, context, output formats, and agent coordination.',ROOT+'decisions/','<p>Choose an architecture by the failure it solves and the acceptance test it can pass. These guides compare operating choices without assuming that the more complex option is better.</p>'+cards([(g['title'],ROOT+'decisions/'+g['slug']+'/',g['summary']) for g in DECISIONS]),'CollectionPage')
    glossary='<p>Use these definitions to make a business implementation decision. Each term includes an example, a limitation, and a practical follow-up guide.</p><nav aria-label="Glossary terms">'+links([(t[1],'#'+t[0]) for t in GLOSSARY])+'</nav>'
    glossary+=''.join(f'<section aria-labelledby="{slug}"><h2 id="{slug}">{e(term)}</h2><p>{e(definition)}</p><p><strong>Business example:</strong> {e(example)}</p><p><strong>What to check:</strong> {e(check)}</p><p><a href="{url}">Apply this concept in a workflow</a></p></section>' for slug,term,definition,example,check,url in GLOSSARY)
    glossary+='<h2>Technical references</h2><p>Explore <a href="https://developers.openai.com/api/docs/guides/retrieval">OpenAI retrieval documentation</a> and <a href="https://www.anthropic.com/research/effective-context-engineering-for-ai-agents">Anthropic context engineering guidance</a> for deeper technical detail.</p>'
    page('AI Business Glossary','Sixteen AI terms explained with business examples, practical limitations, and implementation guides.',ROOT+'glossary/',glossary,'CollectionPage')
    page('Search the AI Guide Directory',f'Find the right resource across {len(resources())} AI workflow, implementation, industry, and architecture guides.',ROOT+'directory/',directory(),'CollectionPage')
    page('AI Pilot Readiness Planner','Identify the missing prerequisites for an AI pilot and prepare a practical next-step plan.',ROOT+'readiness-planner/',planner())
    return pages


def directory():
    rows=resources();groups=sorted({r[2] for r in rows})
    options=''.join('<option value="'+e(g)+'">'+e(g)+'</option>' for g in groups)
    extra_terms={g['title']:g['answer'] for g in DECISIONS}
    cards=''.join(f'<article class="impl-card directory-card" data-category="{e(category)}" data-search="{e(title + chr(32) + category + chr(32) + desc + chr(32) + url.replace(chr(45),chr(32)) + chr(32) + extra_terms.get(title,chr(32)))}"><h2><a href="{url}">{e(title)}</a></h2><p class="directory-category">{e(category)}</p><p>{e(desc)}</p></article>' for title,url,category,desc in rows)
    return f'''<p>Search by a task, deliverable, industry, or concept. All {len(rows)} guides are linked below and remain available without JavaScript.</p><form id="directory-form" role="search"><label for="directory-query">Search AI guides<input id="directory-query" type="search" placeholder="Try evidence, invoice, agency, or retrieval"></label><label for="directory-category">Filter by collection<select id="directory-category" style="display:block;max-width:100%;padding:12px;font:inherit"><option value="">All collections</option>{options}</select></label><button type="reset">Clear filters</button></form><p id="directory-count" role="status" aria-live="polite">{len(rows)} guides</p><div class="impl-grid">{cards}</div><p id="directory-empty" hidden>No guides match. Try a shorter phrase or choose all collections.</p><script>
(function(){{const form=document.getElementById('directory-form'),query=document.getElementById('directory-query'),category=document.getElementById('directory-category'),cards=Array.from(document.querySelectorAll('.directory-card')),count=document.getElementById('directory-count'),empty=document.getElementById('directory-empty');function update(){{const terms=query.value.toLowerCase().trim().split(/\\s+/).filter(Boolean);let shown=0;for(const card of cards){{const match=(!category.value||card.dataset.category===category.value)&&terms.every(t=>(card.dataset.search||card.textContent).toLowerCase().includes(t));card.hidden=!match;if(match)shown++;}}count.textContent=shown+' of '+cards.length+' guides';empty.hidden=shown!==0;}}form.addEventListener('submit',event=>event.preventDefault());query.addEventListener('input',update);category.addEventListener('change',update);form.addEventListener('reset',()=>{{query.value='';category.value='';update();}});}})();
</script>'''


def planner():
    checks=[('owner','A business owner and reviewer are assigned','Name an accountable business owner, reviewer, and backup before starting.'),('sources','Current sources and data access are approved','Resolve source authority and permitted data use before introducing records.'),('baseline','The current process has a measured baseline','Measure preparation, review, corrections, and time to an accepted result.'),('tests','Routine and exception cases have acceptance criteria','Define expected behavior for normal, missing-data, conflicting, and failed cases.'),('recovery','The pilot has a stop and recovery plan','Document how to stop the pilot and handle incomplete or uncertain results.'),('capacity','Review time and a decision date are reserved','Reserve reviewer capacity and an expand, revise, or stop decision date.')]
    boxes=''.join(f'<label style="display:flex;gap:12px;align-items:flex-start"><input type="checkbox" name="{key}" id="ready-{key}" style="width:auto;margin-top:5px"> <span>{e(label)}</span></label>' for key,label,message in checks)
    messages=json.dumps({key:message for key,label,message in checks})
    return '''<p>This planner checks six practical prerequisites. It is a planning checklist, not a validated risk score or a guarantee of readiness. The result stays in your browser and no account is required.</p><form id="readiness-form">'''+boxes+'''<button type="submit">Build my next-step plan</button></form><div id="readiness-result" class="impl-result" role="status" aria-live="polite">Choose the statements supported by your current pilot evidence, then build your plan.</div><h2>How to use the plan</h2><p>Unchecked items become concrete next steps. Owner and approved-source gaps come first because the other work depends on them. Even when every prerequisite is present, run a bounded pilot and inspect actual output quality before expanding.</p><p><a href="/ai/implementation/templates/">Copy the pilot and evaluation templates</a>, <a href="/ai/implementation/content-and-rollout/thirty-day-ai-rollout/">follow the 30-day rollout</a>, and <a href="/ai/implementation/roi-calculator/">estimate review-adjusted economics</a>.</p><noscript><p>Without JavaScript, use the six statements above as a checklist. Resolve missing ownership and source approval first, then establish the baseline, test cases, recovery procedure, and review capacity.</p></noscript><script>
(function(){const form=document.getElementById('readiness-form'),out=document.getElementById('readiness-result'),steps='''+messages+''';form.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(form),missing=Object.keys(steps).filter(key=>!data.has(key)),count=Object.keys(steps).length-missing.length;const heading=document.createElement('h2');heading.textContent=count+' of 6 prerequisites documented';const intro=document.createElement('p');intro.textContent=missing.length?'Next steps before expanding the pilot:':'All six prerequisites are documented. Run the bounded pilot, inspect accepted quality and full operating cost, and record an expand, revise, or stop decision.';const list=document.createElement('ol');for(const key of missing){const item=document.createElement('li');item.textContent=steps[key];list.append(item);}out.replaceChildren(heading,intro,list);});})();
</script>'''
